#!/usr/bin/env python3
"""Emit explicit environment and open discharge obligations for selected atoms."""
import json
from pathlib import Path
import re
ROOT = Path(__file__).resolve().parents[4]
text = (ROOT/'providers/qcore-provider-librdkafka/contracts/librdkafka/cjson.qv').read_text()
formal = dict(detach_chain='chain', detach_distinct='distinct', detach_empty='empty', detach_first_prev='firstPrev', detach_last_next='lastNext', detach_link_targets='linkTargets', detach_no_writer='noWriter', detach_parent_outside='parentOutside', detach_predecessor='predecessor')
quantifiers = dict(detach_chain='all child identities; all adjacent sequence decompositions; all nonempty next paths', detach_distinct='all finite sequence indices', detach_empty='the unique child pointer and finite sequence head', detach_first_prev='all first/last identities matching sequence endpoints', detach_last_next='all last identities matching the sequence endpoint', detach_link_targets='all children x and all nonnull next/prev targets y', detach_no_writer='all steps in the call trace whose actor differs from the current invocation', detach_parent_outside='the parent and every child', detach_predecessor='all adjacent sequence decompositions')
rows=[]
for atom, statement in re.findall(r'resource_hypothesis\((detach_\w+), "([^"\n]+)"\)', text):
 rows.append(dict(id=atom, statement=statement, proposition='QCore.CjsonRepresentationPremises.'+formal[atom], environment='Environment e: callActor, parent, finite children list, ownedChild/live predicates, child/next/prev maps, interleaved trace with per-step actors', quantifiers=quantifiers[atom], conclusion=formal[atom]+' e', environment_bindings={'parent':'the removed-result call actual parent, source-to-Nat identity binding open','children':'the finite exact owned-child sequence at call entry, heap interpretation open','child_next_prev':'the entry heap link maps; equations retained as relational propositions','trace':'every interleaved step during the call within the exact bounds, with callActor distinguishing the detach invocation from other actors; only other-actor link writes are excluded; exclusion is assumed, never inferred from finite observation'}, prerequisites=['exact per-result context identity','source-to-model mapping of the selected removed-result declaration'], disposition='open', warrant='declared', discharge='Supply independent context-bound proof/evidence of this proposition; source observations alone do not establish caller heaps or interference exclusion. Prove prose/formal correspondence separately.'))
result = dict(declaration='cJSON_DetachItemViaPointer', original_premise='detach_list_representation', conjunction='detach_representation_atoms', equivalence='open: no prose-to-formal or C extraction theorem', context_coordinates=['artifact','property','semantic_profile','scope','bounds','assumptions','source_identity','build_identity','evidence_version'], atoms=rows, conditional_conclusions=['live owned link targets exclude parent (chain/linkTargets/parentOutside)','equal child identities imply equal indices (distinct)','an other-actor link-writing trace step refutes noWriter'], next_cycle_design={'all_prerequisites':'v1 conjunction only; each antecedent remains open until exact evidence', 'branch_alternatives':'proposed ||-> needs branch-indexed evidence and every feasible-path safety obligation', 'forbidden_transition':'proposed !-> needs explicit negative proposition; Unknown is not negation', 'terminal_postcondition':'proposed ->| can state terminal condition but does not prove eventual termination', 'proceed_and':'proposed |-> needs exact state-transition semantics before grammar expansion'})
result['formal_implications'] = [
 {'id':'entry-link-target-custody', 'theorem':'QCore.CjsonRepresentationPremises.links_stay_live_owned_and_exclude_parent', 'environment':'Environment e; child identities x,y', 'prerequisite_atoms':['detach_chain','detach_link_targets','detach_parent_outside'], 'additional_antecedents':['x is in e.children','e.next x = some y or e.prev x = some y'], 'conclusion':'e.live y and e.ownedChild y and y differs from e.parent', 'boundary':'Entry heap implication only; no call-transition preservation or source binding.'},
 {'id':'finite-child-index-injectivity', 'theorem':'QCore.CjsonRepresentationPremises.distinct_indices_identify_distinct_children', 'environment':'Environment e; indices i,j : Fin e.children.length', 'prerequisite_atoms':['detach_distinct'], 'additional_antecedents':['e.children[i] = e.children[j]'], 'conclusion':'i = j', 'boundary':'Conditional finite-list result; does not establish caller distinctness.'},
 {'id':'other-writer-refutation', 'theorem':'QCore.CjsonRepresentationPremises.a_writing_step_refutes_no_writer', 'environment':'Environment e; Step step', 'prerequisite_atoms':[], 'additional_antecedents':['step is in e.trace','step.actor differs from e.callActor','step.writesLinks = true'], 'conclusion':'not noWriter e', 'affected_atom':'detach_no_writer', 'affected_premise':'detach_representation_atoms', 'boundary':'Refutes the assumed antecedent in this mathematical environment; not a validated reachable C violation. Original legacy premise remains separately open.'}
]
result['premise_dependency_map'] = {'detach_representation_atoms':[row['id'] for row in rows], 'detach_list_representation':'separate legacy atom; no proved equivalence edge to proposed conjunction'}
print(json.dumps(result,indent=2))
